input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?s ?class ?id WHERE {
  ?s a brick:Zone ? .
  ?s brick:hasIdentifiers ?id .
  ?s a ?class .
}

